import { test, expect } from '@playwright/test';

test.describe('Expand Row to See Nested Details', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should expand a row and display nested details', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get the expand button for the first row
    const expandButton = page.getByRole('button', { name: /expand row/i }).first();
    await expect(expandButton).toBeVisible();

    // Click the expand button
    await expandButton.click();

    // Verify nested details container is visible
    const nestedDetails = page.getByRole('region', { name: /nested details/i });
    await expect(nestedDetails).toBeVisible();

    // Verify nested details contain expected content
    const detailContent = page.getByText('Nested item 1');
    await expect(detailContent).toBeVisible();

    const detailCount = page.getByText(/nested item/i).count();
    expect(detailCount).toBeGreaterThan(0);

    // Verify expand button text changes to collapse
    const collapseButton = page.getByRole('button', { name: /collapse row/i });
    await expect(collapseButton).toBeVisible();
  });

  test('should collapse an expanded row and hide nested details', async ({ page }) => {
    // Get the expand button for the first row
    const expandButton = page.getByRole('button', { name: /expand row/i }).first();
    await expect(expandButton).toBeVisible();

    // Click to expand the row
    await expandButton.click();

    // Verify nested details are visible
    const nestedDetails = page.getByRole('region', { name: /nested details/i });
    await expect(nestedDetails).toBeVisible();

    // Get the collapse button
    const collapseButton = page.getByRole('button', { name: /collapse row/i });
    await expect(collapseButton).toBeVisible();

    // Click the collapse button
    await collapseButton.click();

    // Verify nested details are no longer visible
    await expect(nestedDetails).not.toBeVisible();

    // Verify expand button text reverts
    const expandButtonAfterCollapse = page.getByRole('button', { name: /expand row/i }).first();
    await expect(expandButtonAfterCollapse).toBeVisible();
  });
});
